import { Gauge, ExternalLink } from 'lucide-react';
import { Card, CardHeader, Badge } from './ui.jsx';
import bench from '../lib/benchmarks.json';

const pct = (v) => `${(100 * v).toFixed(1)}%`;
const num = (v, unit) => (unit === 'chunks/s' || unit === 'tokens/s' || unit === 's' ? v.toFixed(1) : Math.round(v).toLocaleString());

/** Before/after results of the benchmark suite (bench/), generated by `npm run bench:report`. */
export default function BenchmarksCard() {
  if (!bench.quality.length && !bench.speed.length) return null;
  return (
    <Card>
      <CardHeader
        icon={Gauge}
        title="Measured performance"
        subtitle={`Before and after the latest improvements, on public benchmarks and in a real browser${bench.hardware ? ` (${bench.hardware})` : ''}`}
        right={
          <a className="inline-flex items-center gap-1 text-sm text-brand-700 hover:underline dark:text-brand-400" href="https://github.com/joelraj18/RAG-AI-Project#performance-before-and-after" target="_blank" rel="noreferrer noopener">
            How it was measured <ExternalLink className="h-3.5 w-3.5" />
          </a>
        }
      />
      <div className="grid gap-6 p-6 pt-3 md:grid-cols-2">
        <div>
          <div className="eyebrow mb-2">Answers and search</div>
          <ul className="space-y-2.5">
            {bench.quality.map((m) => (
              <li key={m.id} className="text-sm">
                <div className="flex items-baseline justify-between gap-3">
                  <span className="font-medium">{m.label}</span>
                  <span className="tabular-nums whitespace-nowrap text-slate-600 dark:text-slate-300">
                    {pct(m.before)} → <b className="text-ink dark:text-slate-50">{pct(m.after)}</b>
                  </span>
                </div>
                <div className="relative mt-1 h-1.5 rounded-full bg-slate-100 dark:bg-slate-800" aria-hidden="true">
                  <div className="absolute inset-y-0 left-0 rounded-full bg-brand-300 dark:bg-brand-800" style={{ width: `${100 * m.before}%` }} />
                  <div className="absolute inset-y-0 left-0 rounded-full bg-brand-600 dark:bg-brand-400" style={{ width: `${100 * Math.max(m.after, 0)}%`, opacity: 0.85 }} />
                </div>
                <div className="mt-0.5 text-xs text-slate-500">{m.note}</div>
              </li>
            ))}
          </ul>
        </div>
        <div>
          <div className="eyebrow mb-2">Local models, no GPU</div>
          <ul className="space-y-2.5">
            {bench.speed.map((m) => (
              <li key={m.id} className="flex items-center justify-between gap-3 text-sm">
                <span>
                  <span className="font-medium">{m.label}</span>
                  <span className="block text-xs text-slate-500 tabular-nums">
                    {num(m.before, m.unit)} → {num(m.after, m.unit)} {m.unit}
                  </span>
                </span>
                <Badge color={m.factor >= 1.05 ? 'green' : 'slate'}>{m.factor.toFixed(1)}× {m.id === 'download' ? 'smaller' : 'faster'}</Badge>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </Card>
  );
}
